# Практика: распарси события пользователя GitHub

Объединим HTTP-запрос и парсинг JSON. Ты получишь события пользователя GitHub и превратишь их в структуры, а затем выведешь в человекочитаемом виде. Это почти готовый финальный проект.

## Задача

1. Получить события пользователя через GitHub API.
2. Распарсить JSON в слайс структур `Event`.
3. Вывести каждое событие понятной фразой, например: «Запушил коммиты в octocat/Hello-World».

## Структура проекта

```
github-activity/
├── go.mod
└── main.go
```

## Решение

```go
package main

import (
    "encoding/json"
    "fmt"
    "net/http"
    "os"
    "time"
)

type Event struct {
    Type    string  `json:"type"`
    Repo    Repo    `json:"repo"`
    Payload Payload `json:"payload"`
}

type Repo struct {
    Name string `json:"name"`
}

type Payload struct {
    Commits []Commit `json:"commits"`
}

type Commit struct {
    Message string `json:"message"`
}

func fetchEvents(username string) ([]Event, error) {
    url := "https://api.github.com/users/" + username + "/events"
    client := http.Client{Timeout: 10 * time.Second}

    resp, err := client.Get(url)
    if err != nil {
        return nil, fmt.Errorf("ошибка сети: %w", err)
    }
    defer resp.Body.Close()

    if resp.StatusCode != http.StatusOK {
        return nil, fmt.Errorf("статус %d", resp.StatusCode)
    }

    var events []Event
    if err := json.NewDecoder(resp.Body).Decode(&events); err != nil {
        return nil, fmt.Errorf("ошибка парсинга: %w", err)
    }
    return events, nil
}

func describe(e Event) string {
    switch e.Type {
    case "PushEvent":
        return fmt.Sprintf("Запушил %d коммит(ов) в %s",
            len(e.Payload.Commits), e.Repo.Name)
    case "WatchEvent":
        return fmt.Sprintf("Поставил звезду репозиторию %s", e.Repo.Name)
    case "CreateEvent":
        return fmt.Sprintf("Создал что-то в %s", e.Repo.Name)
    case "ForkEvent":
        return fmt.Sprintf("Форкнул %s", e.Repo.Name)
    case "IssuesEvent":
        return fmt.Sprintf("Работал с issue в %s", e.Repo.Name)
    case "PullRequestEvent":
        return fmt.Sprintf("Работал с pull request в %s", e.Repo.Name)
    default:
        return fmt.Sprintf("%s в %s", e.Type, e.Repo.Name)
    }
}

func main() {
    if len(os.Args) < 2 {
        fmt.Println("Использование: go run main.go <username>")
        return
    }

    events, err := fetchEvents(os.Args[1])
    if err != nil {
        fmt.Println("Ошибка:", err)
        return
    }

    if len(events) == 0 {
        fmt.Println("Нет недавней активности.")
        return
    }

    fmt.Printf("Активность пользователя %s:\n", os.Args[1])
    for _, e := range events {
        fmt.Println(" -", describe(e))
    }
}
```

## Разбор

- `fetchEvents` теперь возвращает готовый `[]Event` — вся работа с сетью и парсингом инкапсулирована.
- `describe` через `switch` переводит технический тип события в понятную фразу.
- `fmt.Sprintf` формирует строку (не печатает, а возвращает) — удобно для тестов.

## Ожидаемый вывод

```bash
$ go run main.go octocat
Активность пользователя octocat:
 - Запушил 2 коммит(ов) в octocat/Hello-World
 - Поставил звезду репозиторию octocat/Spoon-Knife
 - Форкнул octocat/linguist
```

## Проверка тестами

Функцию `describe` легко тестировать — она чистая (не ходит в сеть):

```go
