import "testing"

func TestDescribe(t *testing.T) {
    cases := []struct {
        event Event
        want  string
    }{
        {
            Event{Type: "PushEvent", Repo: Repo{Name: "a/b"},
                Payload: Payload{Commits: []Commit{{}, {}, {}}}},
            "Запушил 3 коммит(ов) в a/b",
        },
        {
            Event{Type: "WatchEvent", Repo: Repo{Name: "x/y"}},
            "Поставил звезду репозиторию x/y",
        },
        {
            Event{Type: "ForkEvent", Repo: Repo{Name: "f/g"}},
