# Практика: CLI с подкомандами add, list, delete, summary

Построим каркас Expense Tracker с четырьмя подкомандами на пакете `flag`. Это профессиональная структура CLI, как у `git` и `docker`. Данные пока хранятся в JSON — фундамент, изученный в Спринте 1.

## Задача

Реализовать CLI с подкомандами:
- `add --description "Кофе" --amount 150` — добавить расход;
- `list` — показать все расходы;
- `delete --id 2` — удалить расход;
- `summary` — общая сумма расходов.

Расходы хранятся в `expenses.json`.

## Структура проекта

```
expense-tracker/
├── go.mod
├── main.go
├── expense.go
└── storage.go
```

## expense.go

```go
package main

type Expense struct {
    ID          int     `json:"id"`
    Description string  `json:"description"`
    Amount      float64 `json:"amount"`
}

func addExpense(expenses []Expense, desc string, amount float64) []Expense {
    id := 1
    for _, e := range expenses {
        if e.ID >= id {
            id = e.ID + 1
        }
    }
    return append(expenses, Expense{ID: id, Description: desc, Amount: amount})
}

func deleteExpense(expenses []Expense, id int) ([]Expense, bool) {
    for i := range expenses {
        if expenses[i].ID == id {
            return append(expenses[:i], expenses[i+1:]...), true
        }
    }
    return expenses, false
}

func total(expenses []Expense) float64 {
    var sum float64
    for _, e := range expenses {
        sum += e.Amount
    }
    return sum
}
```

## storage.go

```go
package main

import (
    "encoding/json"
    "os"
)

const fileName = "expenses.json"

func load() ([]Expense, error) {
    var expenses []Expense
    data, err := os.ReadFile(fileName)
    if err != nil {
        return expenses, nil
    }
    return expenses, json.Unmarshal(data, &expenses)
}

func save(expenses []Expense) error {
    data, err := json.MarshalIndent(expenses, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(fileName, data, 0644)
}
```

## main.go

```go
package main

import (
    "flag"
    "fmt"
    "os"
)

func main() {
    if len(os.Args) < 2 {
        printHelp()
        os.Exit(1)
    }

    expenses, err := load()
    if err != nil {
        fmt.Println("Ошибка загрузки:", err)
        os.Exit(1)
    }

    switch os.Args[1] {
    case "add":
        cmd := flag.NewFlagSet("add", flag.ExitOnError)
        desc := cmd.String("description", "", "описание расхода")
        amount := cmd.Float64("amount", 0, "сумма")
        cmd.Parse(os.Args[2:])

        if *desc == "" || *amount <= 0 {
            fmt.Println("Нужны --description и положительный --amount")
            os.Exit(1)
        }
        expenses = addExpense(expenses, *desc, *amount)
        fmt.Println("Расход добавлен")

    case "list":
        for _, e := range expenses {
            fmt.Printf("%d. %s — %.2f руб.\n", e.ID, e.Description, e.Amount)
        }

    case "delete":
        cmd := flag.NewFlagSet("delete", flag.ExitOnError)
        id := cmd.Int("id", 0, "id расхода")
        cmd.Parse(os.Args[2:])

        var ok bool
        expenses, ok = deleteExpense(expenses, *id)
        if ok {
            fmt.Printf("Расход %d удалён\n", *id)
        } else {
            fmt.Printf("Расход %d не найден\n", *id)
        }

    case "summary":
        fmt.Printf("Всего расходов: %.2f руб.\n", total(expenses))

    default:
        printHelp()
        os.Exit(1)
    }

    if err := save(expenses); err != nil {
        fmt.Println("Ошибка сохранения:", err)
    }
}

func printHelp() {
    fmt.Println("Expense Tracker")
    fmt.Println("  add --description <текст> --amount <число>")
    fmt.Println("  list")
    fmt.Println("  delete --id <число>")
    fmt.Println("  summary")
}
```

