```go
package expense

import (
    "fmt"
    "time"
)

type Expense struct {
    ID          int       `json:"id"`
    Description string    `json:"description"`
    Amount      float64   `json:"amount"`
    Date        time.Time `json:"date"`
}

func (e Expense) String() string {
    return fmt.Sprintf("%s (%.2f руб.)", e.Description, e.Amount)
}

func Add(list []Expense, desc string, amount float64) []Expense {
    return append(list, Expense{
        ID:          nextID(list),
        Description: desc,
        Amount:      amount,
        Date:        time.Now(),
    })
}

func nextID(list []Expense) int {
    max := 0
    for _, e := range list {
        if e.ID > max {
            max = e.ID
        }
    }
    return max + 1
}

func Delete(list []Expense, id int) ([]Expense, bool) {
    for i := range list {
        if list[i].ID == id {
            return append(list[:i], list[i+1:]...), true
        }
    }
    return list, false
}

func Total(list []Expense, month int) float64 {
    var sum float64
    for _, e := range list {
        if month == 0 || int(e.Date.Month()) == month {
            sum += e.Amount
        }
    }
    return sum
}
```

