```go
package main

import (
    "flag"
    "fmt"
    "os"
    "sort"
    "text/tabwriter"

    "omnibank/expense-tracker/internal/expense"
)

const fileName = "expenses.json"

func main() {
    if len(os.Args) < 2 {
        help()
        os.Exit(1)
    }

    list, err := expense.Load(fileName)
    if err != nil {
        fmt.Println("Ошибка загрузки:", err)
        os.Exit(1)
    }

    switch os.Args[1] {
    case "add":
        cmd := flag.NewFlagSet("add", flag.ExitOnError)
        desc := cmd.String("description", "", "описание")
        amount := cmd.Float64("amount", 0, "сумма")
        cmd.Parse(os.Args[2:])
        if *desc == "" || *amount <= 0 {
            fmt.Println("Нужны --description и положительный --amount")
            os.Exit(1)
        }
        list = expense.Add(list, *desc, *amount)
        fmt.Println("Расход добавлен")

    case "list":
        printTable(list)

    case "delete":
        cmd := flag.NewFlagSet("delete", flag.ExitOnError)
        id := cmd.Int("id", 0, "id")
        cmd.Parse(os.Args[2:])
        var ok bool
        list, ok = expense.Delete(list, *id)
        if ok {
            fmt.Printf("Расход %d удалён\n", *id)
        } else {
            fmt.Printf("Расход %d не найден\n", *id)
        }

    case "summary":
        cmd := flag.NewFlagSet("summary", flag.ExitOnError)
        month := cmd.Int("month", 0, "месяц 1-12")
        cmd.Parse(os.Args[2:])
        fmt.Printf("Сумма: %.2f руб.\n", expense.Total(list, *month))

    case "export":
        cmd := flag.NewFlagSet("export", flag.ExitOnError)
        out := cmd.String("output", "expenses.csv", "файл")
        cmd.Parse(os.Args[2:])
        if err := expense.ExportCSV(list, *out); err != nil {
            fmt.Println("Ошибка экспорта:", err)
            os.Exit(1)
        }
        fmt.Printf("Экспортировано в %s\n", *out)

    default:
        help()
        os.Exit(1)
    }

    if err := expense.Save(fileName, list); err != nil {
        fmt.Println("Ошибка сохранения:", err)
    }
}

func printTable(list []expense.Expense) {
    if len(list) == 0 {
        fmt.Println("Расходов нет.")
        return
    }
    sort.Slice(list, func(i, j int) bool {
        return list[i].Amount > list[j].Amount
    })
    w := tabwriter.NewWriter(os.Stdout, 0, 4, 2, ' ', 0)
    fmt.Fprintln(w, "ID\tДАТА\tОПИСАНИЕ\tСУММА")
    for _, e := range list {
        fmt.Fprintf(w, "%d\t%s\t%s\t%.2f\n",
            e.ID, e.Date.Format("2006-01-02"), e.Description, e.Amount)
    }
    w.Flush()
}

func help() {
    fmt.Println("Expense Tracker — учёт расходов")
    fmt.Println("  add --description <текст> --amount <число>")
    fmt.Println("  list")
    fmt.Println("  delete --id <число>")
    fmt.Println("  summary [--month N]")
    fmt.Println("  export [--output file.csv]")
}
